-- Weekly Arena 2026-11-16: 10 questions, all unseen.
insert into public.arenas(id,title,description,starts_at,ends_at,duration_minutes,status,questions)
values('0cb01d71-8b8a-44ee-8381-6d6b951ea0e0','Weekly Arena — 2026-11-16','A fresh weekly set of 10 problems across Algebra, Geometry, Combinatorics and Number Theory. Open for 7 days; 60 minutes once you begin.','2026-11-16T00:00:00.000Z','2026-11-23T00:00:00.000Z',60,'published','[{"id":"gen-aime-com-020","title":"Inclusion–exclusion in a crowd","question":"How many integers from $1$ through 638 are divisible by 5 or 8?","correctAnswer":"191","solution":"The inclusion–exclusion count is 191.","hint":"Add both multiples and subtract the overlap.","topic":"Combinatorics","level":"Advanced","competition":"AIME","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":47,"difficulty":-0.52},{"id":"gen-amc-num-023","title":"Coprime choices","question":"How many positive integers less than 60 are coprime to 60?","correctAnswer":"16","solution":"$\\varphi(60)=16$.","hint":"Use Euler’s product over distinct prime factors.","topic":"Number Theory","level":"Foundation","competition":"AMC","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":47,"difficulty":-0.52},{"id":"num-f01","title":"A Long Power, Reduced","question":"Find the remainder when $7^{2026}$ is divided by $1000$.","correctAnswer":"649","solution":"Since $7^{100}\\equiv1\\pmod{1000}$, reduce $2026$ to $26$. Repeated squaring gives $7^{16}\\equiv601$, $7^8\\equiv801$, and $7^2=49\\pmod{1000}$. Therefore $7^{26}\\equiv601\\cdot801\\cdot49\\equiv649\\pmod{1000}$.","hint":"The Carmichael period of units modulo $1000$ divides $100$. Reduce the exponent, then use repeated squaring.","topic":"Number Theory","level":"Foundation","competition":"AMC","estimatedSteps":4,"abstraction":3,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":60,"difficulty":0},{"id":"alg-f01","title":"The Hidden Pair","question":"A positive real $x$ satisfies $x+1/x=3$. Find $x^2+1/x^2$.","correctAnswer":"7","solution":"Squaring gives $x^2+2+x^{-2}=9$, so $x^2+x^{-2}=7$.","hint":"Square the given reciprocal sum and subtract the middle term.","topic":"Algebra","level":"Foundation","competition":"AMC","estimatedSteps":2,"abstraction":1,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":34,"difficulty":-1.04},{"id":"gen-amc-geo-014","title":"A regular hexagon","question":"A regular hexagon has side 8. Find its area divided by $\\sqrt3$.","correctAnswer":"96","solution":"$K=6(\\sqrt3/4)8^2$, so $K/\\sqrt3=96$.","hint":"Split the hexagon into six equilateral triangles.","topic":"Geometry","level":"Foundation","competition":"AMC","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":49,"difficulty":-0.44},{"id":"gen-amc-com-019","title":"Distinct digits, one residue","question":"How many 4-digit integers have distinct digits and are divisible by $3$?","correctAnswer":"1548","solution":"Enumerating residue-compatible digit sets and valid leading digits gives 1548.","hint":"Group digit sets by their sum modulo 3 and handle a leading zero separately.","topic":"Combinatorics","level":"Foundation","competition":"AMC","estimatedSteps":5,"abstraction":4,"type":"text","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"points":73,"difficulty":0.52},{"id":"gen-amc-num-022","title":"A long power, reduced","question":"Find the remainder when $3^{2026}$ is divided by $1000$.","correctAnswer":"329","solution":"$3^{2026}\\equiv329\\pmod{1000}$.","hint":"Reduce the exponent with a period, then use repeated squaring.","topic":"Number Theory","level":"Foundation","competition":"AMC","estimatedSteps":4,"abstraction":3,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":60,"difficulty":0},{"id":"gen-aime-geo-010","title":"Altitude from area","question":"A right triangle has legs 7 and 24, with hypotenuse 25. Write the altitude as a reduced fraction and find its numerator.","correctAnswer":"168","solution":"Equating the two area formulas gives altitude $168/25=168/25$. Its numerator is 168.","hint":"Compute the area in two ways, then reduce the fraction.","topic":"Geometry","level":"Advanced","competition":"AIME","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":49,"difficulty":-0.44},{"id":"gen-amc-com-015","title":"Choose without order","question":"How many 2-person teams can be chosen from 8 distinct people?","correctAnswer":"28","solution":"$\\binom{8}{2}=28$.","hint":"Use a binomial coefficient.","topic":"Combinatorics","level":"Foundation","competition":"AMC","estimatedSteps":2,"abstraction":1,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":34,"difficulty":-1.04},{"id":"gen-amc-alg-006","title":"Evaluate without expanding blindly","question":"Find $P(2)$ for $P(t)=t^3+7t^2-8t+1$.","correctAnswer":"21","solution":"$P(2)=21$ after substitution.","hint":"Evaluate each power at the requested input before combining terms.","topic":"Algebra","level":"Foundation","competition":"AMC","estimatedSteps":3,"abstraction":2,"type":"text","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"points":47,"difficulty":-0.52}]'::jsonb)
on conflict(id) do nothing;
